import React, { useState } from 'react';

function AgeCalculator() {
  const [day, setDay] = useState('');
  const [month, setMonth] = useState('');
  const [year, setYear] = useState('');
  const [age, setAge] = useState(null);
  const [error, setError] = useState('');

  const calculateAge = () => {
    if (!day || !month || !year) {
      setError('Please enter day, month, and year');
      setAge(null);
      return;
    }

    const dayNum = parseInt(day, 10);
    const monthNum = parseInt(month, 10);
    const yearNum = parseInt(year, 10);

    if (monthNum < 1 || monthNum > 12) {
      setError('Invalid month');
      setAge(null);
      return;
    }

    if (dayNum < 1 || dayNum > 31) {
      setError('Invalid day');
      setAge(null);
      return;
    }

    const birthDate = new Date(yearNum, monthNum - 1, dayNum);
    const today = new Date();

    if (birthDate > today) {
      setError('Birth date cannot be in the future');
      setAge(null);
      return;
    }

    let years = today.getFullYear() - birthDate.getFullYear();
    let months = today.getMonth() - birthDate.getMonth();
    let days = today.getDate() - birthDate.getDate();

    if (days < 0) {
      months--;
      const prevMonth = new Date(today.getFullYear(), today.getMonth(), 0);
      days += prevMonth.getDate();
    }

    if (months < 0) {
      years--;
      months += 12;
    }

    setAge({ years, months, days });
    setError('');
  };

  return (
    <div className="container">
      <h1>Age Calculator</h1>
      <div className="input-group">
        <label>Enter your birth date:</label>
        <div className="date-inputs">
          <input
            type="number"
            className="date-input"
            placeholder="Day"
            value={day}
            onChange={(e) => setDay(e.target.value)}
            min="1"
            max="31"
          />
          <input
            type="number"
            className="date-input"
            placeholder="Month"
            value={month}
            onChange={(e) => setMonth(e.target.value)}
            min="1"
            max="12"
          />
          <input
            type="number"
            className="date-input"
            placeholder="Year"
            value={year}
            onChange={(e) => setYear(e.target.value)}
          />
        </div>
        <button className="calculate-btn" onClick={calculateAge}>
          Calculate Age
        </button>
      </div>
      {error && <div className="error">{error}</div>}
      {age && (
        <div className="result">
          <h2>Your Age:</h2>
          <div className="age-display">
            <span className="age-item">{age.years}</span>
            <span className="age-label">years</span>
            <span className="age-item">{age.months}</span>
            <span className="age-label">months</span>
            <span className="age-item">{age.days}</span>
            <span className="age-label">days</span>
          </div>
        </div>
      )}
    </div>
  );
}

export default AgeCalculator;
